// Mapea correo -> intake normalizado (contrato ONIA Core v0.5.0).
// ORG_BY_MAILBOX: buzon destino -> organizationId de DentalGest.
// PILOTO: org-demo-001 (Clinica Dental Demo). Agregar clinicas reales aqui.
const ORG_BY_MAILBOX = {
  'oninteligenciaartificial@gmail.com': 'org-demo-001',
};
const DEFAULT_ORG_ID = 'org-demo-001';

const results = [];
for (const item of $input.all()) {
  const email = item.json;
  // Gmail trigger (simple) y formato completo: extraccion defensiva
  const toRaw = String(email.to?.value?.[0]?.address ?? email.To ?? email.to ?? '').toLowerCase();
  const fromAddress = String(email.from?.value?.[0]?.address ?? email.From ?? email.from ?? '').toLowerCase().replace(/.*<([^>]+)>.*/, '$1').trim();
  const fromName = String(email.from?.value?.[0]?.name ?? '').trim() || undefined;
  const subject = String(email.subject ?? email.Subject ?? '(sin asunto)');
  const bodyText = String(email.textPlain ?? email.snippet ?? email.text ?? '').slice(0, 1500);

  const mailboxKey = Object.keys(ORG_BY_MAILBOX).find((mb) => toRaw.includes(mb));
  const organizationId = mailboxKey ? ORG_BY_MAILBOX[mailboxKey] : DEFAULT_ORG_ID;

  results.push({
    json: {
      organizationId,
      channel: 'email_shared',
      message: (subject + '\n\n' + bodyText).trim(),
      contact: { name: fromName, email: fromAddress || undefined },
      receivedAt: email.date ? new Date(email.date).toISOString() : new Date().toISOString(),
    },
  });
}
return results;
